WITH ч AS (SELECT entity_kind AS вид, entity_name AS имя, block_ord AS блок, col AS стб, row_ord AS стр, CASE WHEN value ~ '^[*` ]*[0-9]{1,6}[*` ]*$' THEN regexp_replace(value, '[^0-9]', '', 'g')::bigint END AS n, lower(value) AS низ FROM project_document_cells WHERE project_id = $1), итог AS (SELECT DISTINCT ч.вид, ч.имя, ч.блок, ч.стр AS строка_итога FROM ч JOIN scheme($1) t ON t.role = 'word.total' AND ч.низ ~ ('^[*` ]*' || lower(t.value)) WHERE ч.стб = 0), сверка AS (SELECT и.вид, и.имя, и.блок, ч.стб, max(CASE WHEN ч.стр = и.строка_итога THEN ч.n END) AS сказан, sum(CASE WHEN ч.стр <> и.строка_итога AND ч.стр > 0 THEN ч.n END) AS сумма, count(*) FILTER (WHERE ч.стр <> и.строка_итога AND ч.стр > 0) AS строк, count(ч.n) FILTER (WHERE ч.стр <> и.строка_итога AND ч.стр > 0) AS чисел FROM итог и JOIN ч ON ч.вид = и.вид AND ч.имя = и.имя AND ч.блок = и.блок AND ч.стб > 0 GROUP BY и.вид, и.имя, и.блок, ч.стб) SELECT вид || ' ' || coalesce(nullif(имя, ''), '(одиночный)') || ', столбец ' || стб || ': итог ' || сказан || ', а сумма строк ' || сумма AS detail FROM сверка WHERE сказан IS NOT NULL AND сумма IS NOT NULL AND строк = чисел AND строк > 1 AND сказан <> сумма ORDER BY 1
